mapper.select:
select e.equip_id, e.equip_cd, e.equip_nm, e.plant_cd, h.node_cd, l.conn_mode, coalesce(l.terminal_id, 0) as terminal_id, t.terminal_cd, l.adapter_url, coalesce(l.hb_sec, 5) as hb_sec, coalesce(l.write_enabled_yn, 'N') as write_enabled_yn, coalesce(l.use_yn, 'N') as use_yn, l.last_seen_at, l.last_seq, l.pack_state, l.pack_mode, l.pack_at, l.lost_at, l.row_ver, (select count(*) from cms_equip_cmd c where c.equip_id = e.equip_id and c.status in ('REQUESTED', 'SENT', 'CLAIMED', 'WRITTEN')) as open_cmd_cnt, (select count(*) from cms_alarm_log a where a.equip_id = e.equip_id and a.cleared_at is null) as open_alarm_cnt from mst_equip e left join cms_equip_link l on l.equip_id = e.equip_id left join sys_terminal t on t.terminal_id = l.terminal_id left join mst_equip_hier h on h.node_id = e.node_id where e.use_yn = 'Y' and e.plant_cd = #{plantCd}
and (e.equip_cd ilike #{keyword} escape '\' or e.equip_nm ilike #{keyword} escape '\')
order by (l.equip_id is null), e.plant_cd, h.node_cd nulls last, e.equip_cd limit 1000

mapper.update:
update cms_equip_link
   set conn_mode = #{f.connMode}, terminal_id = #{terminalId}, adapter_url = #{f.adapterUrl}, hb_sec = #{f.hbSec},
       write_enabled_yn = #{f.writeEnabledYn}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where equip_id = #{equipId} and row_ver = #{f.rowVer}

update cms_equip_tag
   set tag_nm = #{f.tagNm}, min_value = #{min}, max_value = #{max}, unit = #{f.unit},
       allowed_states = string_to_array(nullif(#{states}, ''), ',')::varchar(10)[],
       writable_yn = #{f.writableYn}, use_yn = #{f.useYn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tag_id = #{f.tagId} and row_ver = #{f.rowVer}

mapper.select:
select  
 where c.cmd_key = #{cmdKey}
   for update of c

select  
 where c.equip_id = #{equipId}
 order by c.cmd_id desc
 limit #{limit}

select g.log_id, g.equip_id, e.equip_cd, t.terminal_cd, g.event_cd, g.seq_from, g.seq_to, g.detail, g.inbound_id, g.occurred_at, g.recorded_at from cms_equip_link_log g left join mst_equip e on e.equip_id = g.equip_id left join sys_terminal t on t.terminal_id = g.terminal_id
g.equip_id = #{equipId}
order by g.log_id desc limit #{limit}

select equip_id, cons_cd, level_cd, changed_at from cms_equip_consumable
 where equip_id = #{equipId} and cons_cd = #{consCd}
   for update

select terminal_id, boot_id, started_at, last_hb_at, skew_ms, skew_logged_at from cms_edge_session
 where terminal_id = #{terminalId}
   for update
